#!/usr/bin/env node
/**
 * Builds everything the extension and the demo load, from the source files in data/
 * and packages/matcher/.
 *
 *   npm run build          write the generated files
 *   npm run build -- --check   fail if a generated file is out of date (used in CI)
 *
 * Generated files are committed so "Load unpacked" works straight after cloning.
 */
import { createHash } from 'node:crypto';
import { readFile, readdir, writeFile, mkdir } from 'node:fs/promises';
import { existsSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { createRequire } from 'node:module';

const require = createRequire(import.meta.url);
const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const matcherPath = path.join(root, 'packages/matcher/src/matcher.js');
const { validateBundle, normalize } = require(matcherPath);

const checkOnly = process.argv.includes('--check');
const problems = [];

async function readJson(relative) {
  const file = path.join(root, relative);
  try {
    return JSON.parse(await readFile(file, 'utf8'));
  } catch (error) {
    problems.push(`${relative}: ${error.message}`);
    return null;
  }
}

function asScript(globalName, value) {
  return (
    '// Generated by scripts/build.mjs. Do not edit by hand.\n' +
    `globalThis.${globalName} = ${JSON.stringify(value)};\n`
  );
}

async function buildBundle() {
  const game = await readJson('data/game.json');
  const chapters = await readJson('data/chapters.json');
  const spoilerDir = path.join(root, 'data/spoilers');
  const files = (await readdir(spoilerDir)).filter((name) => name.endsWith('.json')).sort();

  const rules = [];
  const termOwners = new Map();

  for (const name of files) {
    const relative = `data/spoilers/${name}`;
    const content = await readJson(relative);
    if (!content) continue;
    if (!Array.isArray(content.rules)) {
      problems.push(`${relative}: must contain a "rules" array`);
      continue;
    }

    const chapterFile = /^chapter-(\d+)\.json$/.exec(name);
    if (!chapterFile && name !== 'generic.json') {
      problems.push(`${relative}: name files "generic.json" or "chapter-NN.json"`);
    }

    for (const rule of content.rules) {
      if (chapterFile && rule.chapter !== Number(chapterFile[1])) {
        problems.push(`${relative}: rule "${rule.id}" has chapter ${rule.chapter} but lives in ${name}`);
      }
      for (const term of rule.terms ?? []) {
        const key = normalize(term);
        if (termOwners.has(key)) {
          problems.push(`${relative}: term in rule "${rule.id}" duplicates one in rule "${termOwners.get(key)}"`);
        } else {
          termOwners.set(key, rule.id);
        }
      }
      rules.push(rule);
    }
  }

  if (!game || !chapters) return null;

  const bundle = { ...game, chapters: chapters.chapters, rules };
  const result = validateBundle(bundle);
  if (!result.ok) problems.push(...result.errors.map((error) => `bundle: ${error}`));

  const listVersion = createHash('sha256').update(JSON.stringify(bundle)).digest('hex').slice(0, 12);
  return { ...bundle, listVersion };
}

async function buildDemoBundle() {
  const demo = await readJson('demo/demo-bundle.json');
  if (!demo) return null;
  const result = validateBundle(demo);
  if (!result.ok) problems.push(...result.errors.map((error) => `demo bundle: ${error}`));
  return demo;
}

async function main() {
  const bundle = await buildBundle();
  const demo = await buildDemoBundle();
  const matcherSource = await readFile(matcherPath, 'utf8');

  if (problems.length) {
    console.error('Data problems:\n- ' + problems.join('\n- '));
    process.exit(1);
  }

  const outputs = {
    'extension/data/bundle.json': JSON.stringify(bundle) + '\n',
    'extension/data/bundle.js': asScript('SPOILER_SHIELD_BUNDLE', bundle),
    'extension/vendor/matcher.js': matcherSource,
    'demo/demo-bundle.js': asScript('SPOILER_SHIELD_DEMO_BUNDLE', demo),
  };

  const stale = [];
  for (const [relative, content] of Object.entries(outputs)) {
    const file = path.join(root, relative);
    const current = existsSync(file) ? await readFile(file, 'utf8') : null;
    if (current === content) continue;
    if (checkOnly) {
      stale.push(relative);
    } else {
      await mkdir(path.dirname(file), { recursive: true });
      await writeFile(file, content);
      console.log(`wrote ${relative}`);
    }
  }

  if (stale.length) {
    console.error('Out of date, run "npm run build" and commit:\n- ' + stale.join('\n- '));
    process.exit(1);
  }

  const terms = bundle.rules.reduce((total, rule) => total + rule.terms.length, 0);
  console.log(
    `${checkOnly ? 'checked' : 'built'} lists ${bundle.listVersion}: ` +
      `${bundle.chapters.length} chapters, ${bundle.rules.length} rules, ${terms} terms`
  );
}

main().catch((error) => {
  console.error(error);
  process.exit(1);
});
